content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-004

=== 用户原始指令 (query.txt) ===
帮我弄个内存清理卡片看比例有数字点一下能进去看日程显示已完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个内存清理卡片看比例有数字点一下能进去看日程显示已完成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "sample-calendar-event-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "卡片对象短标题",
        "sampleValue": "内存清理"
      }
    },
    "memory": {
      "usagePercent": {
        "type": "number",
        "description": "当前内存占用比例数值",
        "sampleValue": 68
      },
      "totalPercent": {
        "type": "number",
        "description": "内存占用比例总量",
        "sampleValue": 100
      },
      "displayPercent": {
        "type": "string",
        "description": "当前内存占用比例展示文本",
        "sampleValue": "68%"
      },
      "cleanableText": {
        "type": "string",
        "description": "可清理内存容量展示文本",
        "sampleValue": "可清2.4G"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程索引项唯一标识符",
              "sampleValue": "sample-calendar-event-001"
            },
            "title": {
              "type": "string",
              "description": "日程标题",
              "sampleValue": "清理提醒"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间",
              "sampleValue": "10:00"
            },
            "description": {
              "type": "string",
              "description": "日程完成状态说明",
              "sampleValue": "已完成"
            }
          }
        ]
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "底部入口短文案",
        "sampleValue": "查看日程"
      }
    }
  },
  "assetCandidates": []
}

